import type { ReactNode } from "react";

/** Centred single-column page used by sign-in, sign-up, and onboarding. */
function AuthShell({
  heading,
  tagline,
  children,
}: {
  heading: string;
  tagline: string;
  children: ReactNode;
}) {
  return (
    <main className="mx-auto flex min-h-screen max-w-md flex-col justify-center gap-6 p-8">
      <div>
        <h1 className="font-medium text-xl">{heading}</h1>
        <p className="text-muted-foreground text-sm">{tagline}</p>
      </div>
      {children}
    </main>
  );
}

export { AuthShell };

import { QueryClientProvider } from "@tanstack/react-query";
import { queryClient } from "../../lib/query-client";

/**
 * Shared module-scoped client so route guards (`loadSession`) and the React
 * tree read the same cache. Do not construct a second QueryClient here.
 */
export function QueryProvider({ children }: { children: React.ReactNode }) {
  return (
    <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>
  );
}

